    auto p=point(copy(s.document,"Spatial pins",2));near(p.x,10,"True3D spatial handle X");near(p.y,10,"True3D spatial handle Y");near(p.z,11,"True3D source retains Z");p=point(copy(s.document,"Curve pins",2));near(p.z,11,"Whole exact native wire reaches its final XYZ endpoint");
    auto middle=point(copy(s.document,"Curve pins",1));const double a=std::hypot(10.,5.),b=std::hypot(10.,6.),t=((a+b)/2-a)/b;near(middle.y,10*t,"Multi-edge native arc-length station",1e-5);near(middle.z,5+6*t,"Multi-edge native arc-length XYZ",1e-5);
    apply(s,R"([{"op":"param.set","name":"pitch","expr":"14"}])");near(point(copy(s.document,"Spatial pins",1)).x,14,"3D handle expression source recomputes");near(point(copy(s.document,"Curve pins",2)).x,14,"Native guide expression recomputes");
    apply(s,R"([{"op":"feature.add","type":"curve","name":"Arc","native":{"start":[10,0,0],"segments":[{"kind":"arc","mode":"three_point","through":[0,10,0],"to":[-10,0,0]}]}},{"op":"assembly.add","name":"Tangent pins","feature":"Pin","pattern":{"type":"curve_driven","count":3,"source":{"feature":"Arc","reference":"path","alignment":"tangent","normal":[0,0,1],"endpoint":"include"}}},{"op":"assembly.add","name":"Links","feature":"Pin","pattern":{"type":"chain","count":3,"source":{"feature":"Arc","reference":"path","alignment":"tangent","normal":[0,0,1],"endpoint":"include","alternate_angle":90}}}])");
    auto tangent=copy(s.document,"Tangent pins",1);near(point(tangent).x,-10,"Relative arc station X");near(point(tangent).y,10,"Relative arc station Y");near(tangent.world.transformDir({1,0,0}).y,1,"Tangent frame rotates seed by90 degrees");near(copy(s.document,"Links",1).world.transformDir({0,0,1}).z,0,"Alternate link orientation is rigid");near(copy(s.document,"Links",2).world.transformDir({0,0,1}).z,1,"Alternate orientation does not accumulate");
    apply(s,R"([{"op":"assembly.add","name":"Guide parent","feature":0,"p":{"tx":100,"ty":-10,"rz":90}},{"op":"assembly.add","name":"Offset seed","feature":"Pin","parent":"Guide parent","p":{"tx":30,"ty":40,"rz":20},"pattern":{"type":"curve_driven","count":3,"source":{"feature":"Arc","reference":"path","alignment":"tangent","normal":[0,0,1],"endpoint":"include"}}},{"op":"assembly.add","name":"Second seed","feature":"Pin","p":{"tx":34,"ty":42,"rz":10}},{"op":"assembly.add","name":"Offset links","feature":"Pin","p":{"tx":30,"ty":40},"pattern":{"type":"chain","count":3,"source":{"feature":"Arc","reference":"path","alignment":"tangent","normal":[0,0,1],"endpoint":"include","alternate_node":"Second seed","alternate_angle":0}}}])");
    near(point(copy(s.document,"Offset seed",1)).x,50,"Tangent placement preserves offset seed in rotated parent frame");near(point(copy(s.document,"Offset seed",1)).y,10,"Source station translation is independent of source absolute origin");near(copy(s.document,"Offset seed",1).world.transformDir({1,0,0}).x,std::cos(deg2rad(200)),"Seed relative rotation and parent rotation compose rigidly");
    near(point(copy(s.document,"Offset links",1)).x,18,"Alternate seed offset rotates about primary seed origin");near(point(copy(s.document,"Offset links",1)).y,54,"Alternate actual seed pose retained along native guide");near(copy(s.document,"Offset links",1).world.transformDir({1,0,0}).x,std::cos(deg2rad(100)),"Alternate actual seed orientation retained");
    apply(s,R"([{"op":"assembly.add","name":"Ground","feature":"Pin","fixed":true,"p":{"tx":60,"ty":80,"rz":30}},{"op":"mate.add","a":"Ground","b":"Tangent pins","type":"rigid"}])");
    near(point(copy(s.document,"Tangent pins",0)).x,60,"Rigid mate solves pattern seed once",1e-5);near(point(copy(s.document,"Tangent pins",1)).x,60-10*std::cos(deg2rad(30))-10*std::sin(deg2rad(30)),"Rigid mate carries exact curve copy position",1e-5);near(point(copy(s.document,"Tangent pins",1)).y,80-10*std::sin(deg2rad(30))+10*std::cos(deg2rad(30)),"Rigid mate carries pattern copies",1e-5);
    rejected(s,R"([{"op":"assembly.edit","id":"Tangent pins","pattern":{"type":"curve_driven","count":3,"source":{"feature":"Arc","reference":"path","alignment":"tangent","normal":[0,1,0]}}}])","DEGENERATE_DIRECTION");
