    apply(s,R"([{"op":"feature.add","type":"curve","name":"Loop","native":{"start":[10,0,0],"segments":[{"kind":"arc","mode":"three_point","through":[0,10,0],"to":[-10,0,0]},{"kind":"arc","mode":"three_point","through":[0,-10,0],"to":[10,0,0]}]}},{"op":"feature.add","type":"box","name":"Outer","p":{"dx":3,"dy":4,"dz":5}},{"op":"assembly.add","name":"Loop links","feature":"Pin","pattern":{"type":"chain","count":4,"source":{"feature":"Loop","reference":"path","alignment":"tangent","normal":[0,0,1],"closed":true,"endpoint":"exclude","alternate_feature":"Outer","alternate_angle":90}}}])");
