    rejected(s,R"([{"op":"assembly.edit","id":"Loop links","pattern":{"type":"chain","count":4,"source":{"feature":"Loop","reference":"path","alignment":"fixed","closed":true,"endpoint":"include"}}}])","CLOSED_ENDPOINT_DUPLICATE");
    rejected(s,R"([{"op":"assembly.edit","id":"Loop links","pattern":{"type":"chain","count":3,"source":{"feature":"Loop","reference":"path","alignment":"fixed","closed":true,"alternate_feature":"Outer"}}}])","CLOSED_ALTERNATION");
    rejected(s,R"([{"op":"assembly.edit","id":"Loop links","pattern":{"type":"chain","count":4,"source":{"feature":"Loop","reference":"path","spacing":"pitch","pitch":10,"alignment":"fixed","closed":true}}}])","CLOSED_PITCH_MISMATCH");
    apply(s,R"([{"op":"feature.add","type":"curve","name":"Helix","native":{"op":"helix","radius":20,"pitch":10,"turns":2}},{"op":"assembly.add","name":"Helix pins","feature":"Pin","pattern":{"type":"curve_driven","count":4,"source":{"feature":"Helix","reference":"path","alignment":"fixed","max_source_error":"0.000001","endpoint":"include"}}}])");near(point(copy(s.document,"Helix pins",3)).z,20,"Helix whole native path endpoint",1e-5);
    rejected(s,R"([{"op":"assembly.edit","id":"Helix pins","pattern":{"type":"curve_driven","count":4,"source":{"feature":"Helix","reference":"path","alignment":"fixed"}}}])","SOURCE_ERROR_BOUND_REQUIRED");
    Document restored;std::string loadError;check(documentFromJson(documentToJson(s.document),restored,&loadError),"Native curve/chain authoring reloads without requiring a pre-existing evaluated body");restored.recompute();near(point(copy(restored,"Helix pins",3)).z,20,"Reload recomputes native guide placement",1e-5);check(copy(restored,"Loop links",1).feature!=copy(restored,"Loop links",2).feature,"Alternate definition link survives native reload");
